INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_product_misuse_017', '(2026) Yue 0105 Civil First 017', 'Small appliance misuse and warning-instruction defense', 'court_gz_ord_proc_032', 'tort liability', 'misuse defense', '2026-05-20', 'Consumer A and Online Store B', 'The user added liquid not permitted by the instructions; the seller must substantiate the instructions and after-sales warning.', 'The user added liquid not permitted by the instructions; the seller must substantiate the instructions and after-sales warning.', 'Simulated legal research only; not legal advice.', 'Supports only a candidate misuse theory requiring counsel review.', 'Preparatory reference.', 'partially supported', 'product liability misuse recall ordinary civil procedure misuse defense');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_seller_recall_notice_008', '(2026) Yue 0105 Civil First 008', 'Seller recall notice and privacy-disclosure boundaries', 'court_gz_ord_proc_032', 'tort liability', 'recall notice', '2026-05-20', 'Consumer A and Online Store B', 'A recall notice requires a confirmed scope and authorization, and any consumer list must be minimally disclosed.', 'A recall notice requires a confirmed scope and authorization, and any consumer list must be minimally disclosed.', 'Simulated legal research only; not legal advice.', 'Supports preserving authorization and privacy boundaries.', 'Preparatory reference.', 'partially supported', 'product liability misuse recall ordinary civil procedure recall notice');
